import { describe, expect, it } from "vitest";
import { PatchRegistry } from "../../../src/runtime/patch-registry";

const NODE_ID = "hero/arm";

function publish(registry: PatchRegistry, tick: number, opacity: number): void {
  registry.beginBatch(tick, [NODE_ID]);
  registry.publish({
    nodeId: NODE_ID,
    values: { opacity },
    sourceProgress: 0,
    status: "ready",
  });
  registry.closeBatch();
}

describe("PatchRegistry: listener snapshots (recovery P1-6)", () => {
  it("delivers a settled batch to a node listener that an earlier listener unsubscribed", () => {
    const registry = new PatchRegistry();
    const seen: string[] = [];
    let releaseSecond: (() => void) | undefined;

    registry.subscribeNode(NODE_ID, () => {
      seen.push("first");
      releaseSecond?.();
    });
    releaseSecond = registry.subscribeNode(NODE_ID, () => {
      seen.push("second");
    });

    publish(registry, 1, 1);
    // The batch was already settled when notification began, so both listeners see it.
    expect(seen).toEqual(["first", "second"]);

    publish(registry, 2, 0.5);
    // The unsubscribe still takes effect for every later batch.
    expect(seen).toEqual(["first", "second", "first"]);
  });

  it("does not deliver a settled batch to a node listener subscribed during notification", () => {
    const registry = new PatchRegistry();
    const seen: string[] = [];

    registry.subscribeNode(NODE_ID, () => {
      seen.push("first");
      if (seen.length === 1)
        registry.subscribeNode(NODE_ID, () => {
          seen.push("late");
        });
    });

    publish(registry, 1, 1);
    expect(seen).toEqual(["first"]);

    publish(registry, 2, 0.5);
    expect(seen).toEqual(["first", "first", "late"]);
  });

  it("node and batch listeners follow the same snapshot rule", () => {
    const registry = new PatchRegistry();
    const nodeSeen: string[] = [];
    const batchSeen: string[] = [];
    let releaseSecondNode: (() => void) | undefined;
    let releaseSecondBatch: (() => void) | undefined;

    registry.subscribeNode(NODE_ID, () => {
      nodeSeen.push("first");
      releaseSecondNode?.();
    });
    releaseSecondNode = registry.subscribeNode(NODE_ID, () => {
      nodeSeen.push("second");
    });
    registry.subscribeBatch(() => {
      batchSeen.push("first");
      releaseSecondBatch?.();
    });
    releaseSecondBatch = registry.subscribeBatch(() => {
      batchSeen.push("second");
    });

    publish(registry, 1, 1);
    expect(nodeSeen).toEqual(batchSeen);
  });
});

packages/react/test/patch-store-lifecycl.source:
import { describe, expect, it } from "vitest";
import { PatchRegistry, type Patch } from "../../core/src/runtime/patch-registry";
import { createPatchStore } from "../src/patch-store";

const NODE_ID = "hero/arm";

function publish(registry: PatchRegistry, tick: number, opacity: number): void {
  registry.beginBatch(tick, [NODE_ID]);
  registry.publish({
    nodeId: NODE_ID,
    values: { opacity },
    sourceProgress: 0,
    status: "ready",
  });
  registry.closeBatch();
}

describe("React patch store lifecycle (C1)", () => {
  it("receives patches again after the last listener leaves and a new one arrives", () => {
    const registry = new PatchRegistry();
    const store = createPatchStore(registry, NODE_ID);

    const mounted: number[] = [];
    const unmount = store.subscribe((patch) => mounted.push(patch.revision));
    publish(registry, 1, 1);
    expect(mounted).toEqual([1]);

    unmount();
    // Published while nothing is mounted: no listener may run, but the store must not keep
    // reporting the patch it happened to see before it was torn down.
    publish(registry, 2, 0.5);

    const remounted: number[] = [];
    const unmountAgain = store.subscribe((patch) => remounted.push(patch.revision));
    expect(store.getSnapshot()?.revision).toBe(2);
    expect(store.getSnapshot()?.values).toEqual({ opacity: 0.5 });

    publish(registry, 3, 0);
    expect(remounted).toEqual([3]);
    expect(mounted).toEqual([1]);
    expect(store.getSnapshot()?.revision).toBe(3);

    unmountAgain();
  });

  it("survives a StrictMode-style double mount without duplicating deliveries", () => {
    const registry = new PatchRegistry();
    const store = createPatchStore(registry, NODE_ID);
    const seen: number[] = [];
    const listener = (patch: Patch): void => {
      seen.push(patch.revision);
    };

    // StrictMode runs the subscribe effect, tears it down, and runs it again.
    store.subscribe(listener)();
    const unmount = store.subscribe(listener);

    publish(registry, 1, 1);
    // Exactly one delivery proves the first attach was released instead of leaked.
    expect(seen).toEqual([1]);

    unmount();
    publish(registry, 2, 0);
    expect(seen).toEqual([1]);
    expect(store.getSnapshot()?.revision).toBe(2);
  });
});

